    ["<Assistant_Title1>睡莲镇长</>\n<Assistant_Title2>成就分类：</>跑团-秩序世界\n<Assistant_Title2>解锁条件：</>睡莲小镇秩序世界完成度到达100%"] = "<Assistant_Title1>Water Lily Mayor</>\n<Assistant_Title2>Achievement Category: </>TRPG-Order World\n<Assistant_Title2>Unlock Condition: </>Reach 100% completion in the Water Lily Town Order World",
