    ["<Chat_Highlight>%s</>势力占领了<Chat_Highlight>%s</>"] = "The <Chat_Highlight>%s</> faction has occupied <Chat_Highlight>%s</>.",
    ["<Chat_Highlight>%s</>势力占领了<Chat_Highlight>%s</>，最高据点倍率达到了%s，势不可挡！"] = "The <Chat_Highlight>%s</> faction has occupied <Chat_Highlight>%s</>, and the highest stronghold multiplier has reached %s. Unstoppable!",
    ["<Chat_Highlight>%s</>势力攻占了<Chat_Highlight>%s</>"] = "The <Chat_Highlight>%s</> faction has captured <Chat_Highlight>%s</>.",
    ["<Chat_Highlight>%s</>势力攻破了<Chat_Highlight>%s</>"] = "The <Chat_Highlight>%s</> faction has breached <Chat_Highlight>%s</>.",
    ["<Chat_Highlight>%s</>向愚者献上了新的名讳。从此，灰雾之上的注视将落向——<Chat_Highlight>%s</>。愿祂庇佑这个名字，不被疯狂吞没。"] = "<Chat_Highlight> %s </> has offered a new honorific name to the Fool. From now on, the gaze from above the gray fog will fall upon—<Chat_Highlight> %s </>. May He shelter this name from being swallowed by madness.",
    ["<Chat_Highlight>%s</>已加入家族专属群聊"] = "<Chat_Highlight>%s</> has joined the family group chat.",
    ["<Chat_Highlight>%s</>救治了濒死的你。"] = "<Chat_Highlight>%s</> saved your dying self.",
    ["<Chat_Highlight>%s</>的<Chat_Highlight>%s</>对你造成了<Chat_Green>%d</>点治疗<Chat_Highlight>%s</>。"] = "<Chat_Highlight> %s </>'s <Chat_Highlight> %s </> healed you for <Chat_Green> %d </> points <Chat_Highlight> %s </>.",
    ["<Chat_Highlight>%s</>离开了家族专属群聊"] = "<Chat_Highlight>%s</> has left the family group chat.",
    ["<Chat_Highlight>%s</>被移出了家族专属群聊"] = "<Chat_Highlight>%s</> has been removed from the Family exclusive group chat.",
    ["<Chat_Highlight>{{eventMessageParams.loserName}}</>沉沦于<Chat_Highlight>{{eventMessageParams.winnerName}}</>的绝对魅力之下，甘愿成为<Chat_Highlight>{{eventMessageParams.winnerName}}</>的俘虏。（状态持续<Chat_Highlight>15</>分钟）"] = "<Chat_Highlight> {{eventMessageParams.loserName}} </> has fallen under the absolute charm of <Chat_Highlight>{{eventMessageParams.winnerName}}</> and is willing to become a captive of <Chat_Highlight>{{eventMessageParams.winnerName}}</>. (Status lasts for <Chat_Highlight>15</> minutes)",
    ["<Chat_Highlight>{{eventMessageParams.winnerName}}</>反制了<Chat_Highlight>{{eventMessageParams.loserName}}</>的魅惑，将其轻松驯服，并感叹魔女的滋味真不错啊。（状态持续<Chat_Highlight>15</>分钟）"] = "<Chat_Highlight> {{eventMessageParams.winnerName}} </> has countered the charm of <Chat_Highlight>{{eventMessageParams.loserName}}</>, easily taming them, and sighed that the Taste of the Witch is truly quite good. (Status lasts for <Chat_Highlight>15</> minutes)",
    ["<Chat_Highlight>未知目标</>的<Chat_Highlight>%s</>对你造成了<Chat_Green>%d</>点治疗<Chat_Highlight>%s</>。"] = "<Chat_Highlight> Unknown target </>'s <Chat_Highlight> %s </> caused you <Chat_Green> %d </> points of healing <Chat_Highlight> %s </>.",
    ["<Chat_Locate>范围设置</>"] = "<Chat_Locate> Range Settings </>",
