    ["<Chat_Telegram>赞美愚者！</>{{player.name}}<Chat_Telegram>被命运眷顾，自灵界召唤获得了</>{{item.name}}<Chat_Telegram>，令风尚之光重现世间！</>"] = "<Chat_Telegram> Praise the Fool! </>{{player.name}}<Chat_Telegram> has been favored by fate and has summoned </>{{item.name}}<Chat_Telegram> from the Spirit World, bringing the light of fashion back to the world! </>",
    ["<Color_Apprentice>近战刺客</>"] = "<Color_Apprentice>Melee Assassin</>",
    ["<Color_Bard>近战输出</>"] = "<Color_Bard>Melee Output</>",
