    ["Tri_左软空气墙"] = "Tri_Left soft air wall",
    ["Tri_雕像Start"] = "Tri_Statue Start",
    ["True:无视cd；\nFalse:cd生效"] = "True: Ignore CD; \n False: CD takes effect",
    ["True:无视反伤伤害；\nFalse:不无视"] = "True: Ignore Damage Reflection; \nFalse: Do not ignore",
    ["True:监听所有Buff；\nFalse:只监听匹配BuffIDs、BuffTags、BuffTypes的Buff"] = "True: Listen for all Buffs; \n False: Only listen for Buffs matching BuffIDs, BuffTags, BuffTypes",
    ["True:监听所有技能；\nFalse:只监听匹配SkillIDs、SkillTags、SkillTypes的技能"] = "True: Listen to all Skills; \nFalse: Only listen to Skills matching SkillIDs, SkillTags, SkillTypes",
    ["True:监听被动技能；\nFalse:不监听被动技能"] = "True: Listen to Passive Skills; \nFalse: Do not listen to Passive Skills",
    ["Type \"<HyperLink stylename=\"h\">风暴比烈酒更烈</>\" in the <h>[Nearby]/[World]</> chat bar"] = "Type \"<HyperLink stylename=\"h\">The storm is fiercer than strong liquor</>\" in the <h>[Nearby]/[World]</> chat bar",
    ["T死亡"] = "T Dead",
    ["T蓝桥"] = "T Blue Bridge",
    ["UE5欧式古风神秘学MMO"] = "UE5 European-style Occult MMO",
    ["UI名称"] = "UI name",
    ["UI界面上交任务"] = "Turn in quest via UI interface",
    ["UI相机移动"] = "UI Camera Movement",
    ["UI类型"] = "UI type",
    ["UI镜头-奉献碑1"] = "UI camera - Offering monument 1",
    ["UI镜头-奉献碑2"] = "UI Lens - Offering Monument 2",
    ["UI镜头-奉献碑3"] = "UI Camera - Monument 3",
