    ["[EventSystemV2:dumpLeakEvents] 存在泄露，eventType:%s, callbackName:%s, target:%s"] = "[EventSystemV2:dumpLeakEvents] Leak detected, eventType:%s, callbackName:%s, target:%s",
    ["[EventSystemV2:publishInternal] 找不到对应的callback，eventType:%s, callbackName:%s, target:%s, isDestroyed:%s"] = "[EventSystemV2:publishInternal] Callback not found, eventType: %s, callbackName: %s, target: %s, isDestroyed: %s",
