    ["local coeffData = {\n    [2] = {\n        [2] = {  -- 2非凡\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 1956, min = 1.10, max = 1.30},\n            p50     = {score = 2264, min = 1.30, max = 1.50},\n            p70     = {score = 2572, min = 1.50, max = 1.70},\n            baseprice  = 150000\n        },\n        [1] = {  -- 1非凡+1普通\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 1368, min = 1.10, max = 1.30},\n            p50     = {score = 1627, min = 1.30, max = 1.50},\n            p70     = {score = 1886, min = 1.50, max = 1.70},\n            baseprice  = 70000\n        },\n        [0] = {  -- 2普通\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 781, min = 1.10, max = 1.30},\n            p50     = {score = 991, min = 1.30, max = 1.50},\n            p70     = {score = 1201, min = 1.50, max = 1.70},\n            baseprice  = 50000\n        }\n    },\n    [1] = {\n        [1] = {  -- 1非凡\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 978, min = 1.10, max = 1.30},\n            p50     = {score = 1132, min = 1.30, max = 1.50},\n            p70     = {score = 1286, min = 1.50, max = 1.70},\n            baseprice  = 30000\n        },\n        [0] = {  -- 1普通\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 390, min = 1.10, max = 1.30},\n            p50     = {score = 495, min = 1.30, max = 1.50},\n            p70     = {score = 600, min = 1.50, max = 1.70},\n            baseprice  = 10000\n        }\n    }\n}\n\nlocal data = coeffData[$2] and coeffData[$2][$3]\n\nlocal minCoeff, maxCoeff, baseprice\nif not data  then\n    minCoeff = 0.5\n    maxCoeff = 1.5\n    baseprice = 10000\nelseif $1 > data.p70.score then\n    minCoeff, maxCoeff = data.p70.min, data.p70.max\n    baseprice = data.baseprice\nelseif $1 > data.p50.score then\n    minCoeff, maxCoeff = data.p50.min, data.p50.max\n    baseprice = data.baseprice\nelseif $1 > data.p30.score then\n    minCoeff, maxCoeff = data.p30.min, data.p30.max\n    baseprice = data.baseprice\nelse\n    minCoeff, maxCoeff = data.Default.min, data.Default.max\n    baseprice = data.baseprice\nend\n\nlocal step = 0.05\nlocal steps = Floor((maxCoeff - minCoeff) / step + 0.5)\nlocal randIndex = Random(0, steps)\nlocal result = minCoeff + randIndex * step\n\nreturn Round(Floor(result * 100 + 0.5) / 100 * baseprice)"] = "local coeffData = {\n    [2] = {\n        [2] = {  -- 2 Beyonder\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 1956, min = 1.10, max = 1.30},\n            p50     = {score = 2264, min = 1.30, max = 1.50},\n            p70     = {score = 2572, min = 1.50, max = 1.70},\n            baseprice  = 150000\n        },\n        [1] = {  -- 1 Beyonder+1 Ordinary\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 1368, min = 1.10, max = 1.30},\n            p50     = {score = 1627, min = 1.30, max = 1.50},\n            p70     = {score = 1886, min = 1.50, max = 1.70},\n            baseprice  = 70000\n        },\n        [0] = {  -- 2 Ordinary\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 781, min = 1.10, max = 1.30},\n            p50     = {score = 991, min = 1.30, max = 1.50},\n            p70     = {score = 1201, min = 1.50, max = 1.70},\n            baseprice  = 50000\n        }\n    },\n    [1] = {\n        [1] = {  -- 1 Beyonder\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 978, min = 1.10, max = 1.30},\n            p50     = {score = 1132, min = 1.30, max = 1.50},\n            p70     = {score = 1286, min = 1.50, max = 1.70},\n            baseprice  = 30000\n        },\n        [0] = {  -- 1 Ordinary\n            Default = {min = 0.90, max = 1.10},\n            p30     = {score = 390, min = 1.10, max = 1.30},\n            p50     = {score = 495, min = 1.30, max = 1.50},\n            p70     = {score = 600, min = 1.50, max = 1.70},\n            baseprice  = 10000\n        }\n    }\n}\n\nlocal data = coeffData[$2] and coeffData[$2][$3]\n\nlocal minCoeff, maxCoeff, baseprice\nif not data  then\n    minCoeff = 0.5\n    maxCoeff = 1.5\n    baseprice = 10000\nelseif $1 > data.p70.score then\n    minCoeff, maxCoeff = data.p70.min, data.p70.max\n    baseprice = data.baseprice\nelseif $1 > data.p50.score then\n    minCoeff, maxCoeff = data.p50.min, data.p50.max\n    baseprice = data.baseprice\nelseif $1 > data.p30.score then\n    minCoeff, maxCoeff = data.p30.min, data.p30.max\n    baseprice = data.baseprice\nelse\n    minCoeff, maxCoeff = data.Default.min, data.Default.max\n    baseprice = data.baseprice\nend\n\nlocal step = 0.05\nlocal steps = Floor((maxCoeff - minCoeff) / step + 0.5)\nlocal randIndex = Random(0, steps)\nlocal result = minCoeff + randIndex * step\n\nreturn Round(Floor(result * 100 + 0.5) / 100 * baseprice)",
    ["local coeffData = {\n    [2] = {\n        [2] = {  -- 2非凡\n            baseprice  = 150000\n        },\n        [1] = {  -- 1非凡+1普通\n            baseprice  = 70000\n        },\n        [0] = {  -- 2普通\n            baseprice  = 50000\n        }\n    },\n    [1] = {\n        [1] = {  -- 1非凡\n            baseprice  = 30000\n        },\n        [0] = {  -- 1普通\n            baseprice  = 10000\n        }\n    }\n}\n\nlocal data = coeffData[$2] and coeffData[$2][$3]\n\nlocal minCoeff, maxCoeff, baseprice\nif not data  then\n    baseprice = 10000\nelse\n    baseprice = data.baseprice\nend\nreturn Round(baseprice)"] = "local coeffData = {\n    [2] = {\n        [2] = {  -- 2 Beyonder \n            baseprice  = 150000\n        },\n        [1] = {  -- 1 Beyonder + 1 Common \n            baseprice  = 70000\n        },\n        [0] = {  -- 2 Common \n            baseprice  = 50000\n        }\n    },\n    [1] = {\n        [1] = {  -- 1 Beyonder \n            baseprice  = 30000\n        },\n        [0] = {  -- 1 Common \n            baseprice  = 10000\n        }\n    }\n}\n\nlocal data = coeffData[$2] and coeffData[$2][$3]\n\nlocal minCoeff, maxCoeff, baseprice\nif not data  then\n    baseprice = 10000\nelse\n    baseprice = data.baseprice\nend\nreturn Round(baseprice)",
