    ["{\n\"上层传入LockTarget\": \"0\",\n\"持有者\": \"1\",\n\"始作俑者\": \"2\",\n\"一仇目标\": \"3\"\n}"] = "{\n \"Upper layer passed LockTarget\": \"0\", \n \"Holder\": \"1\", \n \"Originator\": \"2\", \n \"Primary aggro target\": \"3\" \n}",
    ["{\n\"不指定\":\"\",\n\"全体敌方玩家\": \"Enemy(Player)\",\n\"全体敌方玩家（包含尸体）\": \"Enemy(Player)(IncludeDead)\"\n}"] = "{\n \"Not specified\": \"\", \n \"All enemy players\": \"Enemy(Player)\", \n \"All enemy players (including corpses)\": \"Enemy(Player)(IncludeDead)\" \n}",
    ["{\n\"不指定\":\"\",\n\"命中目标数（技能和法术场中的范围命中后使用该参数）\":\"hitnum\",\n\"筛选目标数（使用目标筛选时使用该参数）\": \"tarnum\",\n\"职业资源改变值（包括向上溢出值）\": \"propdiff\",\n\"职业资源改变值（实际改变值）\": \"proprealdiff\"\n}"] = "{\n \"Unspecified\": \"\", \n \"Hit target count (use this parameter after range hit in skills and spell fields)\": \"hitnum\", \n \"Filter target count (use this parameter when using target filtering)\": \"tarnum\", \n \"Class resource change value (including upward overflow value)\": \"propdiff\", \n \"Class resource change value (actual change value)\": \"proprealdiff\" \n}",
    ["{\n\"不指定类型\": \"\",\n\"中性Buff\": \"0\",\n\"增益Buff\": \"1\",\n\"减益Buff\": \"2\"\n}"] = "{\n \"Not specified type\": \"\", \n \"Neutral Buff\": \"0\", \n \"Buff\": \"1\", \n \"Debuff\": \"2\" \n}",
    ["{\n\"从胶囊体中心开始算距离\": \"False\",\n\"从胶囊体边缘开始算距离\": \"True\"\n}"] = "{\n \"Calculate distance from capsule center\": \"False\", \n \"Calculate distance from capsule edge\": \"True\" \n}",
    ["{\n\"全体(默认值)\":\"All\",\n\"敌方\": \"Enemy\",\n\"友方（不包含自己）\": \"Friend\",\n\"友方\": \"FriendAndSelf\",\n}"] = "{\n \"All (default value)\": \"All\", \n \"Enemy\": \"Enemy\", \n \"Friendly (excluding self)\": \"Friend\", \n \"Friendly\": \"FriendAndSelf\", \n}",
    ["{\n\"全体玩家\": \"0\",\n\"技能/buff持有者\": \"1\",\n\"锁定目标\": \"2\"\n}"] = "{\n \"All players\": \"0\", \n \"Skill/buff holder\": \"1\", \n \"Locked target\": \"2\" \n}",
    ["{\n\"变多or变少\": \"both\",\n\"变少\": \"down\",\n\"变多\": \"up\"\n}"] = "{ \n \"Increase or decrease\": \"both\", \n \"Decrease\": \"down\", \n \"Increase\": \"up\" \n }",
    ["{\n\"大风车（摇杆方向，全身动画）\": \"0\",\n\"滚轮子（面向方向，全身动画）\": \"1\",\n\"滑板鞋（摇杆方向，半身动画）\": \"2\",\n\"踱步挠头（面向方向，全身动画）\": \"3\"\n}"] = "{\n \"Big Windmill (joystick direction, full-body animation)\": \"0\", \n \"Wheel rolling (facing direction, full-body animation)\": \"1\", \n \"Skateboard shoes (joystick direction, half-body animation)\": \"2\", \n \"Pacing and scratching head (facing direction, full-body animation)\": \"3\" \n}",
    ["{\n\"怪物\": \"1\",\n\"NPC\": \"2\",\n\"场景物件\": \"3\"\n}"] = "{\n\"Monster\": \"1\",\n\"NPC\": \"2\",\n\"Scene Object\": \"3\"\n}",
    ["{\n\"技能/buff对象目标(持有者/始作俑者)\": \"0\",\n\"关卡/场景为目标\": \"1\",\n\"范围内对象为目标\": \"2\",\n\"目标筛选为目标\": \"3\",\n\"黑板 tarlist\":\"4\"\n}"] = "{\n \"Skill/buff object target (holder/originator)\": \"0\", \n \"Level/scene as target\": \"1\", \n \"Objects in range as target\": \"2\", \n \"Target filter as target\": \"3\", \n \"Blackboard tarlist\": \"4\" \n}",
    ["{\n\"按下或抬起\": \"both\",\n\"按下\": \"down\",\n\"抬起\": \"up\"\n}"] = "{ \n \"Press or release\": \"both\", \n \"Press\": \"down\", \n \"Release\": \"up\" \n }",
    ["{\n\"无\": \"\",\n\"减速\": \"SpeedDown\",\n\"睡眠\": \"Sleep\",\n\"禁锢\": \"Stuck\",\n\"眩晕\": \"Dizzy\",\n\"沉默\": \"Silent\",\n\"恐惧\": \"CharTerror\",\n\"僵直\": \"Stiff\",\n\"滞涩\": \"DodgeLimit\"\n}"] = "{\n\"None\": \"\", \n\"Slow\": \"SpeedDown\", \n\"Slumber\": \"Sleep\", \n\"Imprisonment\": \"Stuck\", \n\"Stun\": \"Dizzy\", \n\"Silence\": \"Silent\", \n\"Horror\": \"CharTerror\", \n\"Stiff\": \"Stiff\", \n\"Stagnation\": \"DodgeLimit\"\n}",
    ["{\n\"无\": \"\",\n\"减速\": \"SpeedDown\",\n\"睡眠\": \"Sleep\",\n\"禁锢\": \"Stuck\",\n\"眩晕\": \"Dizzy\",\n\"沉默\": \"Silent\",\n\"滞涩\": \"DodgeLimit\"\n}"] = "{\n \"None\": \"\", \n \"Slow\": \"SpeedDown\", \n \"Sleep\": \"Sleep\", \n \"Imprisonment\": \"Stuck\", \n \"Stun\": \"Dizzy\", \n \"Silence\": \"Silent\", \n \"Stagnation\": \"DodgeLimit\" \n}",
    ["{\n\"无\": \"\",\n\"击退\": \"HitBack\",\n\"击倒\": \"HitDown\",\n\"击飞\": \"HitFly\",\n\"挑空\": \"HitFloat\",\n\"拖拽\": \"HitDrag\",\n\"僵直\": \"HitStiff\"\n}"] = "{\n \"None\": \"\", \n \"Knockback\": \"HitBack\", \n \"Knockdown\": \"HitDown\", \n \"Knockup\": \"HitFly\", \n \"Launch\": \"HitFloat\", \n \"Pull\": \"HitDrag\", \n \"Stagger\": \"HitStiff\" \n}",
    ["{\n\"无\": \"\",\n\"隐身\": \"Stealth\",\n\"嘲讽\": \"Taunt\",\n\"霸体\": \"Endure\",\n\"恐惧\": \"Terror\",\n\"隐身(仅免疫锁定)\": \"CharacterStealth\",\n\"石化\": \"StoneState\",\n\"通用Boss机制\": \"NormalBossMechanism\"\n}"] = "{\n \"None\": \"\", \n \"Invisibility\": \"Stealth\", \n \"Taunt\": \"Taunt\", \n \"Super Armor\": \"Endure\", \n \"Horror\": \"Terror\", \n \"Invisibility (Lock-on immunity only)\": \"CharacterStealth\", \n \"Petrification\": \"StoneState\", \n \"General Boss Mechanism\": \"NormalBossMechanism\" \n}",
    ["{\n\"无限制\": \"0\",\n\"限制技能复活\": \"1\",\n\"限制自身功能复活\": \"2\",\n\"禁止复活\": \"3\"\n}"] = "{\n \"No restriction\": \"0\", \n \"Restrict skill resurrection\": \"1\", \n \"Restrict self-function resurrection\": \"2\", \n \"Prohibit resurrection\": \"3\" \n}",
    ["{\n\"根据道具表\": \"1\",\n\"绑定\": \"2\",\n\"非绑定\": \"3\"\n}"] = "{\n \"According to item table\": \"1\", \n \"Bound\": \"2\", \n \"Non-bound\": \"3\" \n}",
    ["{\n\"监听销毁（默认）\": \"false\",\n\"监听死亡技能\": \"true\"\n}"] = "{\n\"Listen for destruction (default)\": \"false\", \n\"Listen for Death Skill\": \"true\"\n}",
    ["{\n\"限制为走路速度\": \"1\",\n\"限制为跑步速度\": \"2\"\n}"] = "{\n\"Restrict to Walking Speed\": \"1\",\n\"Restrict to Running Speed\": \"2\"\n}",
    ["{\n\"随state结束而打断\": \"0\",\n\"随技能结束而打断\": \"1\",\n\"不打断\": \"2\"\n}"] = "{\n \"Interrupt with state end\": \"0\", \n \"Interrupt with skill end\": \"1\", \n \"Do not interrupt\": \"2\" \n}",
    ["{\n点击后自动取消高亮: \"0\",\n点击后不会自动取消高亮: \"1\",\n}"] = "{\n \"Automatically cancel highlight after click\": \"0\", \n \"Do not automatically cancel highlight after click\": \"1\", \n}",
    ["{ {skillTag1, 1.0}, {skillTag2, 2.0}} 意思是把skillTag1的技能提升1倍速率，skillTag2的技能提升2倍速率"] = "{ {skillTag1, 1.0}, {skillTag2, 2.0}} means increasing the speed of skillTag1 skills by 1x and skillTag2 skills by 2x.",
    ["{ {skillType1, 1.0}, {skillType2, 2.0}} 意思是把skillType1的技能提升1倍速率，skillType2的技能提升2倍速率"] = "{ {skillType1, 1.0}, {skillType2, 2.0}} means increasing the speed of skillType1 skills by 1x and skillType2 skills by 2x.",
    ["{ {skillid1, 1.0}, {skillid2, 2.0}} 意思是把skillid1提升1倍速率，skillid2提升2倍"] = "{ {skillid1, 1.0}, {skillid2, 2.0}} means increasing the rate of skillid1 by 1 time, and skillid2 by 2 times.",
