    ["{\"id\":1000,\"title\":\"下载已暂停\",\"body\":\"由于您当前的网络环境切换至了流量环境，游戏已暂停下载，当您处于WiFi环境时，我们将自动为您恢复下载。\",\"pushMode\":0,\"delayInSeconds\":1}"] = "{\"id\":1000,\"title\":\"Download Paused\",\"body\":\"Your network environment has switched to mobile data, so the game download has been paused. We will automatically resume the download when you are on a WiFi connection.\",\"pushMode\":0,\"delayInSeconds\":1}",
    ["{\"id\":1000,\"title\":\"正在下载资源\",\"body\":\"正在为您后台下载\",\"pushMode\":0,\"delayInSeconds\":1}"] = "{\"id\":1000,\"title\":\"Downloading Resources\",\"body\":\"Downloading in the background for you\",\"pushMode\":0,\"delayInSeconds\":1}",
