    ["【临时】1红线"] = "[Temporary] 1 Red Line",
    ["【临时】1绿线"] = "【Temporary】 1 green line",
    ["【临时】1蓝线"] = "[Temporary] 1 Blue Line",
    ["【临时】2红线"] = "【Temporary】2 Red Line",
    ["【临时】2绿线"] = "[Temporary] 2 Green Lines",
    ["【临时】2蓝线"] = "【Temporary】2 Blue Lines",
    ["【临时】3红线"] = "[Temporary] 3 Red Lines",
    ["【临时】3绿线"] = "[Temporary] 3 green lines",
