    ["仲裁人npc"] = "Arbiter NPC",
    ["仲裁人专攻"] = "Arbiter Expertise",
    ["仲裁人专攻_数值"] = "Arbiter Expertise_Value",
    ["仲裁人专防"] = "Arbiter Defense Expertise",
