    ["啊 这是"] = "Ah, this is",
    ["啊~咦~呜~喔~喔~"] = "Ah~ ee~ wu~ ooh~ ooh~",
    ["啊——"] = "Ah—",
    ["啊——<P_Heart>（男人的惨叫声）</>"] = "Ah—<P_Heart>(A man's scream)</>",
    ["啊——哈加提苦酒，少女泪水与汗水的味道——"] = "Ah—Hagati bitter wine, the taste of a maiden's tears and sweat—",
    ["啊——啊——赞美——伟大的——主人！"] = "Ah—ah—praise—the great—master!",
