    ["对话镜头2"] = "Dialogue Camera 2",
    ["对谁隐身"] = "Invisible to Whom",
    ["对象传送到指定场景里的指定位置（玩家支持跨场景传送，Npc只能同场景传送）  "] = "Teleport object to a specified location in a specified scene (players support cross-scene teleportation, NPCs only support same-scene teleportation).",
    ["对象使用道具"] = "Object Use Item",
    ["对象同场景传送（支持NPC）"] = "Object teleport within same scene (supports NPCs)",
    ["对象播放指定对白内容"] = "Object plays specified dialogue content",
    ["对象播放指定对白内容  "] = "Object plays specified dialogue content.",
    ["对象暂时无法附身"] = "The target cannot be possessed at this time.",
    ["对象瞬间使用单次使用17"] = "Object Instant Single Use 17",
