    ["将<LightHighlight>艺术品、酒类</>金色物品转为125%的<HyperLink stylename=\"Underline\" u=\"trainTradeItem=30308\">【冰鲜雪贝薄片】</>"] = "Convert <LightHighlight> Artworks and Alcohol </> Gold Items into 125% of <HyperLink stylename=\"Underline\" u=\"trainTradeItem=30308\"> [Chilled Snow Shell Flakes] </>.",
    ["将<LightHighlight>艺术品、食品</>金色物品转为125%的<HyperLink stylename=\"Underline\" u=\"trainTradeItem=30108\">【珍品迷雾香槟】</>"] = "Convert <LightHighlight> Artworks and Food </> Gold Items into 125% of <HyperLink stylename=\"Underline\" u=\"trainTradeItem=30108\"> [Premium Mist Champagne] </>.",
    ["将<LightHighlight>酒类、食品</>金色物品转为125%的<HyperLink stylename=\"Underline\" u=\"trainTradeItem=30508\">【鎏银宫廷茶具】</>"] = "Convert <LightHighlight> Alcohol and Food </> Gold Items into 125% of <HyperLink stylename=\"Underline\" u=\"trainTradeItem=30508\"> [Silver-Plated Court Tea Set] </>.",
    ["将<h>护身符</>交给布雷登"] = "Give the <h>amulet</> to Brayden",
    ["将<h>日记本</>交给布雷登"] = "Give the <h>diary</> to Brayden",
