    ["尤朵拉"] = "Yodora",
    ["尤朵拉-1星"] = "Yodora - 1 Star",
    ["尤朵拉-2星"] = "Yodora - 2 Star",
    ["尤朵拉-3星"] = "Yodora - 3 Star",
    ["尤朵拉-冲击骨笛-激光-15s"] = "Yodora - Impact Bone Flute - Laser - 15s",
    ["尤朵拉-冲击骨笛-激光-9s-右"] = "Yodora - Impact Bone Flute - Laser - 9s - Right",
