    ["攻击提高<Mark>120</>，防御降低<Mark>15</>。进入战斗时，若队伍中有异性队友，攻击额外提高<Mark>20</>。"] = "Attack increased by <Mark>120</>, Defense decreased by <Mark>15</>. Upon entering combat, if there is a teammate of the opposite gender in the squad, Attack is additionally increased by <Mark>20</>.",
    ["攻击提高<Mark>175</>。"] = "Attack increased by <Mark>175</>.",
    ["攻击提高<Mark>180</>，防御降低<Mark>15</>。进入战斗时，若队伍中有异性队友，攻击额外提高<Mark>20</>。"] = "Attack increased by <Mark>180</>, defense decreased by <Mark>15</>. When entering combat, if there is a teammate of the opposite sex in the party, attack is additionally increased by <Mark>20</>.",
