    ["虫子……远离虫子……"] = "Bugs... stay away from the bugs...",
    ["虫子……都消失了？"] = "The insects... have they all disappeared?",
    ["虫子……都碾碎……"] = "Bugs... crush them all...",
    ["虫子！滚出！我的！房子！"] = "Bugs! Get out! Of my! House!",
    ["虫子！虫子！不要靠近我！"] = "Bugs! Bugs! Don't come near me!",
    ["虫潮，烟火，安魂诗"] = "Insect Swarm, Fireworks, Requiem",
    ["虹"] = "Hong",
    ["虹光染料"] = "Rainbow Dye",
